{
  "claims": [
    {
      "claim_text": "SQLite has offered WAL mode since version 3.7.0.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly states that the WAL option is available beginning with version 3.7.0.",
      "citations": [
        {
          "index": 0,
          "quote": "Beginning with version 3.7.0 (2010-07-21), a new \"Write-Ahead Log\" option (hereafter referred to as \"WAL\") is available."
        }
      ]
    },
    {
      "claim_text": "In WAL mode, writers and readers can run at the same time.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage confirms that because writers do not interfere with readers, they can run simultaneously.",
      "citations": [
        {
          "index": 3,
          "quote": "Because writers do nothing that would interfere with the actions of readers, writers and readers can run at the same time."
        }
      ]
    },
    {
      "claim_text": "In WAL mode, there can only be one writer at a time.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage explicitly states that due to there being only one WAL file, only one writer is allowed at a time.",
      "citations": [
        {
          "index": 3,
          "quote": "However, since there is only one WAL file, there can only be one writer at a time."
        }
      ]
    },
    {
      "claim_text": "A checkpoint runs automatically once the WAL file reaches 1000 pages.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage states that by default, SQLite performs an automatic checkpoint when the WAL file hits a threshold of 1000 pages.",
      "citations": [
        {
          "index": 2,
          "quote": "By default, SQLite does a checkpoint automatically when the WAL file reaches a threshold size of 1000 pages."
        }
      ]
    },
    {
      "claim_text": "The WAL file is normally named after the database file with a \"-wal\" suffix.",
      "verdict": "SUPPORTED",
      "reasoning": "The passage describes the usual naming convention for the WAL file on disk.",
      "citations": [
        {
          "index": 4,
          "quote": "The name of this file on disk is usually the name of the database file with a extra \"-wal\" suffix"
        }
      ]
    }
  ]
}

{
